/// <reference lib="webworker" />

const CACHE_NAME = 'bienve-app-cache-v5';
const urlsToCache = [
  '/',
  '/index.html',
  '/manifest.json',
  '/logo.svg',
  'https://cdn.tailwindcss.com'
];

const sw = self as unknown as ServiceWorkerGlobalScope;

sw.addEventListener('install', (event: ExtendableEvent) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Cache abierto, guardando recursos principales.');
        return cache.addAll(urlsToCache);
      })
  );
});

sw.addEventListener('fetch', (event: FetchEvent) => {
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request)
      .then(cachedResponse => {
        if (cachedResponse) return cachedResponse;

        return fetch(event.request).then(networkResponse => {
          if (!networkResponse || (networkResponse.status !== 200 && networkResponse.type !== 'opaque')) {
            return networkResponse;
          }

          const responseToCache = networkResponse.clone();
          caches.open(CACHE_NAME).then(cache => {
            cache.put(event.request, responseToCache);
          });

          return networkResponse;
        }).catch(() => {
          // Fallback silencioso si falla la red
          return new Response('Offline content not available');
        });
      })
  );
});

sw.addEventListener('activate', (event: ExtendableEvent) => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (!cacheWhitelist.includes(cacheName)) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

export {};

import React, { useState } from 'react';
import { LogoIcon } from './icons';

interface LoginProps {
    onLogin: () => void;
}

// Credenciales fijas para el administrador solicitadas por el usuario
const ADMIN_USERNAME = 'nefta';
const ADMIN_PASSWORD = '2020';

const Login: React.FC<LoginProps> = ({ onLogin }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const handleLoginSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (username.trim() === ADMIN_USERNAME && password === ADMIN_PASSWORD) {
            setError('');
            onLogin();
        } else {
            setError('Usuario o contraseña incorrectos.');
        }
    };

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex items-center justify-center p-4 animate-fade-in">
            <div className="w-full max-w-sm mx-auto">
                <div className="flex justify-center mb-8">
                    <LogoIcon className="w-20 h-20" title="Bienve App Logo" />
                </div>
                <div className="bg-gray-800 p-8 rounded-2xl shadow-xl border border-gray-700 animate-fade-in-scale-up">
                    <h1 className="text-3xl font-bold text-center mb-2 bg-clip-text text-transparent bg-gradient-to-r from-red-500 to-red-700">
                        Bienve App
                    </h1>
                    <p className="text-center text-gray-400 mb-8 font-medium">Panel de Administración</p>

                    <form onSubmit={handleLoginSubmit} className="space-y-6">
                        <div>
                            <label htmlFor="username" className="block text-sm font-medium text-gray-300 mb-2">
                                Usuario
                            </label>
                            <input
                                id="username"
                                type="text"
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                className="w-full bg-gray-900 border-2 border-gray-600 rounded-lg p-3 focus:ring-2 focus:ring-red-500 focus:border-red-500 transition outline-none"
                                required
                                autoFocus
                                autoComplete="username"
                            />
                        </div>
                        <div>
                            <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                Contraseña
                            </label>
                            <input
                                id="password"
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full bg-gray-900 border-2 border-gray-600 rounded-lg p-3 focus:ring-2 focus:ring-red-500 focus:border-red-500 transition outline-none"
                                required
                                autoComplete="current-password"
                            />
                        </div>

                        {error && (
                            <p className="text-red-400 text-sm text-center font-medium animate-pulse">{error}</p>
                        )}

                        <button
                            type="submit"
                            className="w-full px-6 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg transition-all transform hover:scale-[1.02] active:scale-95 duration-200"
                        >
                            Acceder
                        </button>
                    </form>
                </div>
                <p className="text-center text-gray-500 text-xs mt-8">
                    © {new Date().getFullYear()} Bienve App - Acceso Restringido
                </p>
            </div>
        </div>
    );
};

export default Login;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Day, Schedule, DayStatus, DriveUser } from './types';
import { getWeekId, getWeekDays, getWeekTitle, getDaysInMonth } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf, downloadMonthScheduleAsPdf, downloadCustomPeriodPdf } from './services/pdfService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import ApiKeyModal from './components/ApiKeyModal';
import * as GoogleDrive from './services/googleDriveService';
import * as ApiKeyService from './services/apiKeyService';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

const App: React.FC = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) {
            console.error("Failed to load schedule from localStorage", error);
        }
        return {};
    });

    // Google Drive States
    const [driveUser, setDriveUser] = useState<DriveUser | null>(null);
    const [isDriveConnected, setIsDriveConnected] = useState(false);
    const [isDriveLoading, setIsDriveLoading] = useState(false);
    const [driveInitError, setDriveInitError] = useState<string | null>(null);
    const [driveSyncStatus, setDriveSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
    const [showApiKeyModal, setShowApiKeyModal] = useState(!ApiKeyService.areKeysSet());

    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isDownloadingMonth, setIsDownloadingMonth] = useState(false);
    const [isDownloadingCustomPeriod, setIsDownloadingCustomPeriod] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    const syncTimeoutRef = useRef<number | null>(null);

    // Initialization of Google Drive
    const initDrive = useCallback(async () => {
        const keys = ApiKeyService.getApiKeys();
        if (!keys) return;

        setIsDriveLoading(true);
        try {
            await GoogleDrive.initClient(keys.clientId, keys.apiKey, (tokenResponse) => {
                if (tokenResponse && !tokenResponse.error) {
                    setIsDriveConnected(true);
                    const profile = GoogleDrive.getProfile();
                    setDriveUser(profile);
                    // Trigger initial load from drive
                    loadFromDrive();
                }
            });

            // Check if we already have a token
            const profile = GoogleDrive.getProfile();
            if (profile) {
                setDriveUser(profile);
                setIsDriveConnected(true);
                loadFromDrive();
            }
        } catch (error: any) {
            console.error("Drive Init Error:", error);
            setDriveInitError(error.message || "Error al conectar con Google");
        } finally {
            setIsDriveLoading(false);
        }
    }, []);

    useEffect(() => {
        if (isAuthenticated && ApiKeyService.areKeysSet()) {
            initDrive();
        }
    }, [isAuthenticated, initDrive]);

    // Cloud Sync Logic
    const loadFromDrive = async () => {
        setDriveSyncStatus('syncing');
        try {
            const driveData = await GoogleDrive.getSchedule();
            if (driveData && driveData.schedule) {
                setSchedule(prev => {
                    // Merge local and remote: remote takes priority if newer or missing locally
                    const merged = { ...prev, ...driveData.schedule };
                    return merged;
                });
                setDriveSyncStatus('success');
            } else {
                setDriveSyncStatus('idle');
            }
        } catch (error) {
            console.error("Load from drive failed", error);
            setDriveSyncStatus('error');
        }
    };

    const saveToDrive = useCallback(async (currentSchedule: Schedule) => {
        if (!isDriveConnected) return;

        setDriveSyncStatus('syncing');
        try {
            await GoogleDrive.saveSchedule({
                schedule: currentSchedule,
                lastModified: new Date().toISOString()
            });
            setDriveSyncStatus('success');
        } catch (error) {
            console.error("Save to drive failed", error);
            setDriveSyncStatus('error');
        }
    }, [isDriveConnected]);

    // Automatic save effect (Debounced)
    useEffect(() => {
        localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));

        if (isDriveConnected) {
            if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
            syncTimeoutRef.current = window.setTimeout(() => {
                saveToDrive(schedule);
            }, 2000); // 2 seconds delay
        }

        return () => {
            if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
        };
    }, [schedule, isDriveConnected, saveToDrive]);

    useEffect(() => {
        localStorage.setItem(AUTH_STORAGE_KEY, String(isAuthenticated));
    }, [isAuthenticated]);

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }
        const scheduledDaysMap = new Map(schedule[weekId].map(d => [new Date(d.date).toISOString().slice(0, 10), d]));
        return days.map(date => scheduledDaysMap.get(date.toISOString().slice(0, 10)) || { date, shift: '', status: DayStatus.Work });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        setSchedule(prevSchedule => {
            const currentWeekData = prevSchedule[weekId] || weekDays;
            const newWeekDays = [...currentWeekData];
            const dayKey = updatedDay.date.toISOString().slice(0, 10);
            const dayIndex = newWeekDays.findIndex(d => new Date(d.date).toISOString().slice(0, 10) === dayKey);

            if (dayIndex !== -1) {
                newWeekDays[dayIndex] = updatedDay;
            } else {
                newWeekDays.push(updatedDay);
            }
            return { ...prevSchedule, [weekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [weekId, weekDays]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => {
            if (day.status === DayStatus.Work) {
                return acc + calculateHoursFromShift(day.shift);
            }
            return acc;
        }, 0);
        const daysOff = weekDays.filter(d => d.status === DayStatus.Holiday || d.status === DayStatus.Vacation).length;
        const extraDaysOff = Math.max(0, daysOff - 2);
        const weeklyTarget = Math.max(0, 40 - (extraDaysOff * 8));
        return { totalHours: workHours, overtimeHours: workHours - weeklyTarget };
    }, [weekDays]);

    const handlePrevWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() - 7);
        setCurrentDate(newDate);
    };

    const handleNextWeek = () => {
        const newDate = new Date(currentDate);
        newDate.setDate(newDate.getDate() + 7);
        setCurrentDate(newDate);
    };

    const handleDownload = async () => {
        setIsDownloading(true);
        try {
            await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours });
        } catch (error) {
            alert("Error al descargar PDF");
        } finally {
            setIsDownloading(false);
        }
    };

    const handleSaveApiKeys = (keys: { clientId: string, apiKey: string }) => {
        ApiKeyService.saveApiKeys(keys);
        setShowApiKeyModal(false);
        initDrive();
    };

    const handleLogin = () => setIsAuthenticated(true);
    const handleLogout = () => {
        setIsAuthenticated(false);
        setIsLogoutModalOpen(false);
    };

    if (!isAuthenticated) return <Login onLogin={handleLogin} />;
    if (showApiKeyModal) return <ApiKeyModal onSave={handleSaveApiKeys} />;

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={handlePrevWeek}
                onNextWeek={handleNextWeek}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                // Drive Props
                driveUser={driveUser}
                isDriveConnected={isDriveConnected}
                isDriveLoading={isDriveLoading}
                driveInitError={driveInitError}
                driveSyncStatus={driveSyncStatus}
                onDriveSignIn={GoogleDrive.signIn}
                onDriveSignOut={() => { GoogleDrive.signOut(); setIsDriveConnected(false); setDriveUser(null); }}
                onForceSync={loadFromDrive}
                onConfigureApi={() => setShowApiKeyModal(true)}
            />
            <main className="flex-grow py-4 md:py-6 lg:py-8">
                <WeekView days={weekDays} onEditDay={setEditingDay} />
            </main>
            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={handleDownload}
                isDownloading={isDownloading}
                onDownloadMonth={() => {}} // Implementation for Month PDF if needed
                isDownloadingMonth={isDownloadingMonth}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={isDownloadingCustomPeriod}
            />
            {editingDay && (
                <EditShiftModal
                    day={editingDay}
                    onClose={() => setEditingDay(null)}
                    onSave={handleUpdateDay}
                    templates={templates}
                    onManageTemplates={() => setIsManagingTemplates(true)}
                />
            )}
            {isManagingTemplates && (
                <ManageTemplatesModal
                    templates={templates}
                    onAddTemplate={addTemplate}
                    onDeleteTemplate={deleteTemplate}
                    onClose={() => setIsManagingTemplates(false)}
                />
            )}
            {isCalendarOpen && (
                <CalendarPickerModal
                    isOpen={isCalendarOpen}
                    onClose={() => setIsCalendarOpen(false)}
                    currentDate={currentDate}
                    onDateSelect={(d) => { setCurrentDate(d); setIsCalendarOpen(false); }}
                />
            )}
            {isCustomPeriodModalOpen && (
                <CustomPeriodModal
                    isOpen={isCustomPeriodModalOpen}
                    onClose={() => setIsCustomPeriodModalOpen(false)}
                    onConfirm={(start, end) => { /* Custom logic */ setIsCustomPeriodModalOpen(false); }}
                />
            )}
            {isLogoutModalOpen && (
                <ConfirmModal
                    isOpen={isLogoutModalOpen}
                    title="Cerrar Sesión"
                    message="¿Estás seguro de que quieres cerrar la sesión?"
                    onConfirm={handleLogout}
                    onCancel={() => setIsLogoutModalOpen(false)}
                    confirmText="Cerrar Sesión"
                />
            )}
        </div>
    );
};

export default App;

import React from 'react';
import { LogoIcon, ChevronLeftIcon, ChevronRightIcon, CalendarIcon, LogoutIcon } from './icons';
import DriveSync from './DriveSync';
import { DriveUser } from '../types';

interface HeaderProps {
    currentWeekTitle: string;
    onPrevWeek: () => void;
    onNextWeek: () => void;
    onCalendarClick: () => void;
    onLogout: () => void;
    // Drive Props
    driveUser: DriveUser | null;
    isDriveConnected: boolean;
    isDriveLoading: boolean;
    driveInitError: string | null;
    driveSyncStatus: 'idle' | 'syncing' | 'success' | 'error';
    onDriveSignIn: () => void;
    onDriveSignOut: () => void;
    onForceSync: () => void;
    onConfigureApi: () => void;
}

const Header: React.FC<HeaderProps> = ({ 
    currentWeekTitle, 
    onPrevWeek, 
    onNextWeek, 
    onCalendarClick, 
    onLogout,
    driveUser,
    isDriveConnected,
    isDriveLoading,
    driveInitError,
    driveSyncStatus,
    onDriveSignIn,
    onDriveSignOut,
    onForceSync,
    onConfigureApi
}) => {

    return (
        <header className="bg-gray-800 shadow-md p-3 sm:p-4 sticky top-0 z-20">
            <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">

                {/* --- Logo y Drive Status --- */}
                <div className="flex items-center justify-between w-full sm:w-auto space-x-4">
                    <div className="flex items-center space-x-2">
                        <LogoIcon className="w-8 h-8 sm:w-10 sm:h-10" />
                        <h1 className="text-lg sm:text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-red-500 to-red-700 hidden xs:block">
                            Bienve App
                        </h1>
                    </div>

                    <div className="flex items-center space-x-2">
                        <DriveSync 
                            driveUser={driveUser}
                            isDriveConnected={isDriveConnected}
                            isDriveLoading={isDriveLoading}
                            driveInitError={driveInitError}
                            onSignIn={onDriveSignIn}
                            onSignOut={onDriveSignOut}
                            onForceSync={onForceSync}
                            driveSyncStatus={driveSyncStatus}
                            onRetrySync={onForceSync}
                            onConfigureApi={onConfigureApi}
                        />
                    </div>
                </div>

                {/* --- Navegación Central --- */}
                <div className="flex items-center justify-center bg-gray-900/50 p-1 rounded-full border border-gray-700">
                    <button onClick={onPrevWeek} className="p-2 text-gray-400 hover:text-white hover:bg-gray-700 rounded-full transition-colors" aria-label="Semana anterior">
                        <ChevronLeftIcon className="w-5 h-5" />
                    </button>

                    <button 
                        onClick={onCalendarClick}
                        className="flex items-center space-x-2 px-4 py-1.5 text-xs sm:text-sm font-medium text-red-400 hover:text-red-300 transition-colors"
                        title="Seleccionar semana"
                    >
                        <CalendarIcon className="w-4 h-4" />
                        <span className="max-w-[120px] sm:max-w-none truncate">{currentWeekTitle}</span>
                    </button>

                    <button onClick={onNextWeek} className="p-2 text-gray-400 hover:text-white hover:bg-gray-700 rounded-full transition-colors" aria-label="Semana siguiente">
                        <ChevronRightIcon className="w-5 h-5" />
                    </button>
                </div>

                {/* --- Botón Logout --- */}
                <div className="hidden sm:block">
                    <button
                        onClick={onLogout}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-gray-700 rounded-full transition-colors"
                        title="Cerrar sesión"
                    >
                        <LogoutIcon className="w-6 h-6" />
                    </button>
                </div>

                {/* Móvil: Logout en la esquina superior derecha si fuera necesario, 
                    o integrado en el flujo de la barra superior. 
                    Por ahora lo mantenemos visible solo en desktop para limpiar la UI móvil. */}
                <button
                    onClick={onLogout}
                    className="sm:hidden absolute top-3 right-3 p-2 text-gray-500 hover:text-red-500"
                >
                    <LogoutIcon className="w-5 h-5" />
                </button>
            </div>
        </header>
    );
};

export default Header;

import { initializeApp, FirebaseApp } from 'https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js';
import { 
    getFirestore, 
    doc, 
    setDoc, 
    onSnapshot, 
    getDoc, 
    Firestore,
    Unsubscribe
} from 'https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js';
import { Schedule } from '../types';

let app: FirebaseApp | null = null;
let db: Firestore | null = null;

export const initFirestore = (config: any) => {
    try {
        app = initializeApp(config);
        db = getFirestore(app);
        return true;
    } catch (error) {
        console.error("Error inicializando Firebase:", error);
        return false;
    }
};

const USER_DOC_ID = 'nefta'; // Usamos el nombre de usuario administrador como ID de documento

export const saveScheduleToCloud = async (schedule: Schedule) => {
    if (!db) return;
    try {
        const scheduleRef = doc(db, 'schedules', USER_DOC_ID);
        // Convertimos las fechas a string para Firestore
        const serializedSchedule: any = {};
        Object.keys(schedule).forEach(weekId => {
            serializedSchedule[weekId] = schedule[weekId].map(day => ({
                ...day,
                date: day.date.toISOString()
            }));
        });

        await setDoc(scheduleRef, { 
            schedule: serializedSchedule,
            lastModified: new Date().toISOString()
        }, { merge: true });
    } catch (error) {
        console.error("Error al guardar en Firestore:", error);
        throw error;
    }
};

export const subscribeToSchedule = (onUpdate: (schedule: Schedule) => void): Unsubscribe | null => {
    if (!db) return null;

    const scheduleRef = doc(db, 'schedules', USER_DOC_ID);
    return onSnapshot(scheduleRef, (docSnap) => {
        if (docSnap.exists()) {
            const data = docSnap.data();
            const rawSchedule = data.schedule || {};

            // Re-hidratar fechas
            const parsedSchedule: Schedule = {};
            Object.keys(rawSchedule).forEach(weekId => {
                parsedSchedule[weekId] = rawSchedule[weekId].map((day: any) => ({
                    ...day,
                    date: new Date(day.date)
                }));
            });

            onUpdate(parsedSchedule);
        }
    });
};

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Day, Schedule, DayStatus } from './types';
import { getWeekId, getWeekDays, getWeekTitle } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf } from './services/pdfService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import ApiKeyModal from './components/ApiKeyModal';
import * as FirestoreService from './services/firestoreService';
import * as ApiKeyService from './services/apiKeyService';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

const App: React.FC = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    const [currentDate, setCurrentDate] = useState(new Date());
    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) { console.error(error); }
        return {};
    });

    const [isCloudConnected, setIsCloudConnected] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
    const [showApiKeyModal, setShowApiKeyModal] = useState(!ApiKeyService.areKeysSet());

    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    const syncTimeoutRef = useRef<number | null>(null);
    const isInitialLoadRef = useRef(true);

    // Inicializar Firestore
    useEffect(() => {
        if (isAuthenticated && ApiKeyService.areKeysSet()) {
            const keys = ApiKeyService.getApiKeys();
            if (keys) {
                // Firebase keys stored as JSON string in the 'apiKey' field for simplicity
                try {
                    const config = JSON.parse(keys.apiKey);
                    const success = FirestoreService.initFirestore(config);
                    setIsCloudConnected(success);

                    if (success) {
                        // Suscribirse a cambios en tiempo real
                        const unsubscribe = FirestoreService.subscribeToSchedule((newSchedule) => {
                            if (isInitialLoadRef.current) {
                                setSchedule(newSchedule);
                                isInitialLoadRef.current = false;
                            } else {
                                // Solo actualizar si es diferente para evitar bucles
                                setSchedule(prev => {
                                    if (JSON.stringify(prev) !== JSON.stringify(newSchedule)) {
                                        return newSchedule;
                                    }
                                    return prev;
                                });
                            }
                            setSyncStatus('success');
                        });
                        return () => unsubscribe?.();
                    }
                } catch (e) {
                    console.error("Firebase Config Error", e);
                }
            }
        }
    }, [isAuthenticated]);

    // Guardado automático en la nube con Debounce
    useEffect(() => {
        localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));

        if (isCloudConnected && !isInitialLoadRef.current) {
            if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
            setSyncStatus('syncing');
            syncTimeoutRef.current = window.setTimeout(async () => {
                try {
                    await FirestoreService.saveScheduleToCloud(schedule);
                    setSyncStatus('success');
                } catch (e) {
                    setSyncStatus('error');
                }
            }, 1500);
        }
    }, [schedule, isCloudConnected]);

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }
        const scheduledDaysMap = new Map(schedule[weekId].map(d => [new Date(d.date).toISOString().slice(0, 10), d]));
        return days.map(date => scheduledDaysMap.get(date.toISOString().slice(0, 10)) || { date, shift: '', status: DayStatus.Work });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        isInitialLoadRef.current = false; // El usuario está editando, permitimos subir cambios
        setSchedule(prevSchedule => {
            const currentWeekData = prevSchedule[weekId] || weekDays;
            const newWeekDays = [...currentWeekData];
            const dayKey = updatedDay.date.toISOString().slice(0, 10);
            const dayIndex = newWeekDays.findIndex(d => new Date(d.date).toISOString().slice(0, 10) === dayKey);

            if (dayIndex !== -1) newWeekDays[dayIndex] = updatedDay;
            else newWeekDays.push(updatedDay);

            return { ...prevSchedule, [weekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [weekId, weekDays]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => day.status === DayStatus.Work ? acc + calculateHoursFromShift(day.shift) : acc, 0);
        const daysOff = weekDays.filter(d => d.status !== DayStatus.Work).length;
        const weeklyTarget = Math.max(0, 40 - (Math.max(0, daysOff - 2) * 8));
        return { totalHours: workHours, overtimeHours: workHours - weeklyTarget };
    }, [weekDays]);

    const handleLogin = () => {
        localStorage.setItem(AUTH_STORAGE_KEY, 'true');
        setIsAuthenticated(true);
    };

    const handleLogout = () => {
        localStorage.removeItem(AUTH_STORAGE_KEY);
        setIsAuthenticated(false);
        setIsLogoutModalOpen(false);
    };

    if (!isAuthenticated) return <Login onLogin={handleLogin} />;
    if (showApiKeyModal) return <ApiKeyModal onSave={(keys) => { ApiKeyService.saveApiKeys(keys); setShowApiKeyModal(false); window.location.reload(); }} />;

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={() => setCurrentDate(d => { const n = new Date(d); n.setDate(n.getDate() - 7); return n; })}
                onNextWeek={() => setCurrentDate(d => { const n = new Date(d); n.setDate(n.getDate() + 7); return n; })}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                isCloudConnected={isCloudConnected}
                syncStatus={syncStatus}
                onConfigureApi={() => setShowApiKeyModal(true)}
            />
            <main className="flex-grow py-4">
                <WeekView days={weekDays} onEditDay={setEditingDay} />
            </main>
            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={async () => { setIsDownloading(true); await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours }); setIsDownloading(false); }}
                isDownloading={isDownloading}
                onDownloadMonth={() => {}}
                isDownloadingMonth={false}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={false}
            />
            {editingDay && <EditShiftModal day={editingDay} onClose={() => setEditingDay(null)} onSave={handleUpdateDay} templates={templates} onManageTemplates={() => setIsManagingTemplates(true)} />}
            {isManagingTemplates && <ManageTemplatesModal templates={templates} onAddTemplate={addTemplate} onDeleteTemplate={deleteTemplate} onClose={() => setIsManagingTemplates(false)} />}
            {isCalendarOpen && <CalendarPickerModal isOpen={isCalendarOpen} onClose={() => setIsCalendarOpen(false)} currentDate={currentDate} onDateSelect={(d) => { setCurrentDate(d); setIsCalendarOpen(false); }} />}
            {isLogoutModalOpen && <ConfirmModal isOpen={isLogoutModalOpen} title="Cerrar Sesión" message="¿Estás seguro de que quieres salir?" onConfirm={handleLogout} onCancel={() => setIsLogoutModalOpen(false)} />}
        </div>
    );
};

export default App;

