import React, { useState } from 'react';

interface ApiKeyModalProps {
    onSave: (keys: { clientId: string, apiKey: string }) => void;
}

const ApiKeyModal: React.FC<ApiKeyModalProps> = ({ onSave }) => {
    const [firebaseConfig, setFirebaseConfig] = useState('');

    const cleanFirebaseInput = (input: string): string => {
        let cleaned = input.trim();

        if (cleaned.includes('{') && cleaned.includes('}')) {
            const start = cleaned.indexOf('{');
            const end = cleaned.lastIndexOf('}');
            cleaned = cleaned.substring(start, end + 1);
        }

        cleaned = cleaned.replace(/(\w+):\s*["']([^"']+)["']/g, '"$1": "$2"');
        cleaned = cleaned.replace(/,\s*}/g, '}');
        cleaned = cleaned.replace(/'/g, '"');

        return cleaned;
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const jsonString = cleanFirebaseInput(firebaseConfig);
            const parsed = JSON.parse(jsonString);

            if (!parsed.apiKey || !parsed.projectId) {
                throw new Error("Faltan campos obligatorios");
            }

            onSave({ clientId: 'firebase', apiKey: JSON.stringify(parsed) });
        } catch (err) {
            alert('El código no es válido. Copia el bloque completo que te da Firebase.');
        }
    };

    return (
        <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-4 animate-fade-in overflow-y-auto">
            <div className="bg-gray-800 rounded-2xl shadow-2xl w-full max-w-xl p-6 sm:p-8 border border-gray-700 my-8">
                <form onSubmit={handleSave}>
                    <div className="flex justify-center mb-4">
                        <div className="bg-red-500/10 p-3 rounded-full">
                            <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                            </svg>
                        </div>
                    </div>

                    <h2 className="text-2xl font-bold text-white mb-2 text-center">Conectar Mi Nube</h2>

                    <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3 mb-6">
                        <p className="text-amber-400 text-xs font-bold uppercase mb-1 flex items-center gap-2">
                            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
                            Paso Crítico Obligatorio:
                        </p>
                        <p className="text-gray-300 text-[11px] leading-relaxed">
                            Después de pegar el código, debes ir a tu <a href="https://console.firebase.google.com/" target="_blank" className="text-amber-400 underline">Consola de Firebase</a>, entrar en <b>Firestore Database</b> y pulsar <b>"Crear base de datos"</b> en <b>Modo Prueba</b>. Si no lo haces, recibirás un error de permisos.
                        </p>
                    </div>

                    <div className="mb-6">
                        <label className="block text-xs font-medium text-red-400 mb-2 uppercase tracking-widest">
                            Configuración de Firebase:
                        </label>
                        <textarea
                            value={firebaseConfig}
                            onChange={(e) => setFirebaseConfig(e.target.value)}
                            placeholder='const firebaseConfig = { ... };'
                            className="w-full bg-black border-2 border-gray-700 rounded-lg p-4 h-40 font-mono text-[11px] focus:border-red-500 outline-none transition text-green-400"
                            spellCheck={false}
                            required
                        />
                    </div>

                    <div className="flex flex-col gap-3">
                        <button 
                            type="submit" 
                            className="w-full px-6 py-4 bg-red-600 hover:bg-red-500 text-white font-black rounded-xl shadow-lg transition transform active:scale-95 uppercase tracking-widest"
                        >
                            CONECTAR Y SINCRONIZAR
                        </button>
                        <button 
                            type="button"
                            onClick={() => window.location.reload()}
                            className="text-gray-500 text-xs hover:text-white transition py-2"
                        >
                            Usar en modo local temporalmente
