import React, { useState } from 'react';

interface ApiKeyModalProps {
    onSave: (keys: { clientId: string, apiKey: string }) => void;
}

const ApiKeyModal: React.FC<ApiKeyModalProps> = ({ onSave }) => {
    const [inputValue, setInputValue] = useState('');
    const [error, setError] = useState<string | null>(null);

    const extractFirebaseConfig = (text: string) => {
        // Buscamos los valores clave usando expresiones regulares flexibles
        const findValue = (key: string) => {
            const regex = new RegExp(`${key}\\s*:\\s*["']([^"']+)["']`, 'i');
            const match = text.match(regex);
            return match ? match[1] : null;
        };

        const config = {
            apiKey: findValue('apiKey'),
            authDomain: findValue('authDomain'),
            projectId: findValue('projectId'),
            storageBucket: findValue('storageBucket'),
            messagingSenderId: findValue('messagingSenderId'),
            appId: findValue('appId')
        };

        // Verificamos que al menos tengamos los campos críticos
        if (!config.apiKey || !config.projectId) {
            return null;
        }

        return config;
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        const config = extractFirebaseConfig(inputValue);

        if (config) {
            onSave({ 
                clientId: 'firebase', 
                apiKey: JSON.stringify(config) 
            });
        } else {
            setError('No se pudo encontrar una configuración válida. Asegúrate de copiar el bloque completo que empieza por "const firebaseConfig = { ... };"');
        }
    };

    return (
        <div className="fixed inset-0 bg-gray-900 flex items-center justify-center z-50 p-4 animate-fade-in overflow-y-auto">
            <div className="bg-gray-800 rounded-3xl shadow-2xl w-full max-w-xl p-6 sm:p-10 border border-gray-700 my-8">
                <form onSubmit={handleSave} className="space-y-6">
                    <div className="text-center">
