import { initializeApp, getApps, deleteApp, FirebaseApp } from 'https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js';
import { 
    getFirestore, 
    doc, 
    setDoc, 
    onSnapshot, 
    Firestore,
    Unsubscribe
} from 'https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js';
import { 
    getAuth, 
    signInAnonymously 
} from 'https://www.gstatic.com/firebasejs/10.8.0/firebase-auth.js';
import { Schedule } from '../types';

let app: FirebaseApp | null = null;
let db: Firestore | null = null;
let auth: any = null;

export const initFirestore = async (config: any) => {
    try {
        if (!config || !config.apiKey) return false;

        const existingApps = getApps();
        for (const existingApp of existingApps) {
            await deleteApp(existingApp);
        }

        app = initializeApp(config);
        db = getFirestore(app);
        auth = getAuth(app);

        // Autenticación anónima para cumplir con reglas de producción (request.auth != null)
        await signInAnonymously(auth);

        console.log("Firebase y Auth inicializados con éxito");
        return true;
    } catch (error) {
        console.error("Error inicializando Firebase/Auth:", error);
        return false;
    }
};

const USER_DOC_ID = 'nefta'; 

export const saveScheduleToCloud = async (schedule: Schedule) => {
    if (!db) throw new Error("Base de datos no inicializada");
    try {
        const scheduleRef = doc(db, 'schedules', USER_DOC_ID);
        const serializedSchedule: any = {};
        Object.keys(schedule).forEach(weekId => {
            serializedSchedule[weekId] = schedule[weekId].map(day => ({
                ...day,
                date: day.date.toISOString()
            }));
        });

        await setDoc(scheduleRef, { 
            schedule: serializedSchedule,
            lastModified: new Date().toISOString()
        }, { merge: true });
    } catch (error: any) {
        console.error("Error al guardar en Firestore:", error);
        throw error;
    }
};

export const subscribeToSchedule = (
    onUpdate: (schedule: Schedule) => void,
    onError?: (error: any) => void
): Unsubscribe | null => {
    if (!db) return null;

    const scheduleRef = doc(db, 'schedules', USER_DOC_ID);
    return onSnapshot(scheduleRef, 
        (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                const rawSchedule = data.schedule || {};

                const parsedSchedule: Schedule = {};
                Object.keys(rawSchedule).forEach(weekId => {
                    parsedSchedule[weekId] = rawSchedule[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date)
                    }));
                });

                onUpdate(parsedSchedule);
            }
        },
        (error) => {
            const errorMsg = error.message?.toLowerCase() || "";
            if (errorMsg.includes("permission") || errorMsg.includes("insufficient")) {
                console.error("🔒 ERROR DE PERMISOS: La base de datos está bloqueada (if false).");
            } else {
                console.error("Error en suscripción de Firestore:", error);
            }
            if (onError) onError(error);
        }
    );
};

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { Day, Schedule, DayStatus } from './types';
import { getWeekId, getWeekDays, getWeekTitle } from './utils/dateUtils';
import { calculateHoursFromShift } from './services/scheduleService';
import { downloadScheduleAsPdf } from './services/pdfService';
import Header from './components/Header';
import WeekView from './components/WeekView';
import Summary from './components/Summary';
import EditShiftModal from './components/EditShiftModal';
import { useShiftTemplates } from './hooks/useShiftTemplates';
import CalendarPickerModal from './components/CalendarPickerModal';
import ManageTemplatesModal from './components/ManageTemplatesModal';
import CustomPeriodModal from './components/CustomPeriodModal';
import Login from './components/Login';
import ConfirmModal from './components/ConfirmModal';
import ApiKeyModal from './components/ApiKeyModal';
import * as FirestoreService from './services/firestoreService';
import * as ApiKeyService from './services/apiKeyService';
import { ExclamationCircleIcon } from './components/icons';

const SCHEDULE_STORAGE_KEY = 'bienveAppSchedule';
const AUTH_STORAGE_KEY = 'bienveAppIsAuthenticated';

// REGLAS DE PRODUCCIÓN SEGURAS: Solo permiten acceso a usuarios autenticados por la App.
const FIREBASE_RULES = `rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /schedules/{document} {
      allow read, write: if request.auth != null;
    }
  }
}`;

const App: React.FC = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(() => {
        return localStorage.getItem(AUTH_STORAGE_KEY) === 'true';
    });

    const [currentDate, setCurrentDate] = useState(new Date());
    const [cloudConfigVersion, setCloudConfigVersion] = useState(0); 

    const [schedule, setSchedule] = useState<Schedule>(() => {
        try {
            const savedSchedule = localStorage.getItem(SCHEDULE_STORAGE_KEY);
            if (savedSchedule) {
                const parsed = JSON.parse(savedSchedule);
                Object.keys(parsed).forEach(weekId => {
                    parsed[weekId] = parsed[weekId].map((day: any) => ({
                        ...day,
                        date: new Date(day.date),
                    }));
                });
                return parsed;
            }
        } catch (error) { console.error(error); }
        return {};
    });

    const [isCloudConnected, setIsCloudConnected] = useState(false);
    const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
    const [cloudError, setCloudError] = useState<string | null>(null);
    const [isPermissionError, setIsPermissionError] = useState(false);
    const [showApiKeyModal, setShowApiKeyModal] = useState(false);
    const [rulesCopied, setRulesCopied] = useState(false);

    const [editingDay, setEditingDay] = useState<Day | null>(null);
    const { templates, addTemplate, deleteTemplate } = useShiftTemplates();
    const [isManagingTemplates, setIsManagingTemplates] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isCalendarOpen, setIsCalendarOpen] = useState(false);
    const [isCustomPeriodModalOpen, setIsCustomPeriodModalOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

    const syncTimeoutRef = useRef<number | null>(null);
    const isInitialLoadRef = useRef(true);
    const unsubscribeRef = useRef<(() => void) | null>(null);

    const firebaseConsoleUrl = useMemo(() => {
        const keys = ApiKeyService.getApiKeys();
        if (keys && keys.apiKey) {
            try {
                const config = JSON.parse(keys.apiKey);
                if (config.projectId) {
                    return `https://console.firebase.google.com/project/${config.projectId}/firestore/rules`;
                }
            } catch (e) { return null; }
        }
        return null;
    }, [cloudConfigVersion]);

    const handleCloudError = useCallback((error: any) => {
        setSyncStatus('error');
        const errorMsg = (error.message || "").toLowerCase();
        const errorCode = (error.code || "").toLowerCase();

        if (errorCode.includes('permission') || errorMsg.includes('permission') || errorMsg.includes('permisos') || errorMsg.includes('insufficient')) {
            setCloudError("REGLAS BLOQUEADAS: Cambia 'if false' por 'if request.auth != null'");
            setIsPermissionError(true);
        } else if (errorCode.includes('not-found') || errorMsg.includes('not found')) {
            setCloudError("Base de datos inexistente.");
            setIsPermissionError(false);
        } else {
            setCloudError(error.message || "Error de conexión");
            setIsPermissionError(false);
        }
    }, []);

    const copyRulesDirectly = () => {
        navigator.clipboard.writeText(FIREBASE_RULES);
        setRulesCopied(true);
        setTimeout(() => setRulesCopied(false), 3000);
    };

    const initializeCloud = useCallback(async () => {
        if (!isAuthenticated) return;

        if (unsubscribeRef.current) {
            unsubscribeRef.current();
            unsubscribeRef.current = null;
        }

        const keys = ApiKeyService.getApiKeys();
        if (!keys) {
            setIsCloudConnected(false);
            setSyncStatus('idle');
            return;
        }

        try {
            const configText = keys.apiKey;
            if (!configText) throw new Error("Configuración vacía");

            const config = JSON.parse(configText);
            const success = await FirestoreService.initFirestore(config);
            setIsCloudConnected(success);

            if (success) {
                setSyncStatus('syncing');
                setCloudError(null);
                setIsPermissionError(false);
                const unsub = FirestoreService.subscribeToSchedule(
                    (newSchedule) => {
                        if (isInitialLoadRef.current) {
                            if (Object.keys(newSchedule).length > 0) {
                                setSchedule(newSchedule);
                            }
                            isInitialLoadRef.current = false;
                        } else {
                            setSchedule(prev => {
                                if (JSON.stringify(prev) !== JSON.stringify(newSchedule)) {
                                    return newSchedule;
                                }
                                return prev;
                            });
                        }
                        setSyncStatus('success');
                        setCloudError(null);
                        setIsPermissionError(false);
                    },
                    handleCloudError
                );
                unsubscribeRef.current = unsub;
            }
        } catch (e: any) {
            console.error("Firebase Setup Error", e);
            handleCloudError(e);
            setIsCloudConnected(false);
        }
    }, [isAuthenticated, cloudConfigVersion, handleCloudError]);

    useEffect(() => {
        initializeCloud();
        return () => { if (unsubscribeRef.current) unsubscribeRef.current(); };
    }, [initializeCloud]);

    useEffect(() => {
        localStorage.setItem(SCHEDULE_STORAGE_KEY, JSON.stringify(schedule));

        if (isCloudConnected && !isInitialLoadRef.current && syncStatus !== 'error') {
            if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
            setSyncStatus('syncing');
            syncTimeoutRef.current = window.setTimeout(async () => {
                try {
                    await FirestoreService.saveScheduleToCloud(schedule);
                    setSyncStatus('success');
                    setCloudError(null);
                    setIsPermissionError(false);
                } catch (e: any) {
                    handleCloudError(e);
                }
            }, 2000);
        }
    }, [schedule, isCloudConnected, syncStatus, handleCloudError]);

    const weekId = useMemo(() => getWeekId(currentDate), [currentDate]);

    const weekDays = useMemo(() => {
        const days = getWeekDays(currentDate);
        if (!schedule[weekId]) {
            return days.map(date => ({ date, shift: '', status: DayStatus.Work }));
        }
        const scheduledDaysMap = new Map(schedule[weekId].map(d => [new Date(d.date).toISOString().slice(0, 10), d]));
        return days.map(date => scheduledDaysMap.get(date.toISOString().slice(0, 10)) || { date, shift: '', status: DayStatus.Work });
    }, [currentDate, schedule, weekId]);

    const handleUpdateDay = useCallback((updatedDay: Day) => {
        isInitialLoadRef.current = false; 
        setSchedule(prevSchedule => {
            const currentWeekData = prevSchedule[weekId] || weekDays;
            const newWeekDays = [...currentWeekData];
            const dayKey = updatedDay.date.toISOString().slice(0, 10);
            const dayIndex = newWeekDays.findIndex(d => new Date(d.date).toISOString().slice(0, 10) === dayKey);

            if (dayIndex !== -1) newWeekDays[dayIndex] = updatedDay;
            else newWeekDays.push(updatedDay);

            return { ...prevSchedule, [weekId]: newWeekDays };
        });
        setEditingDay(null);
    }, [weekId, weekDays]);

    const { totalHours, overtimeHours } = useMemo(() => {
        const workHours = weekDays.reduce((acc, day) => day.status === DayStatus.Work ? acc + calculateHoursFromShift(day.shift) : acc, 0);
        const daysOff = weekDays.filter(d => d.status !== DayStatus.Work).length;
        const weeklyTarget = Math.max(0, 40 - (Math.max(0, daysOff - 2) * 8));
        return { totalHours: workHours, overtimeHours: workHours - weeklyTarget };
    }, [weekDays]);

    const handleLogin = () => {
        localStorage.setItem(AUTH_STORAGE_KEY, 'true');
        setIsAuthenticated(true);
    };

    const handleLogout = () => {
        localStorage.removeItem(AUTH_STORAGE_KEY);
        setIsAuthenticated(false);
        setIsLogoutModalOpen(false);
    };

    if (!isAuthenticated) return <Login onLogin={handleLogin} />;

    if (showApiKeyModal) return (
        <ApiKeyModal 
            onSave={(keys) => { 
                ApiKeyService.saveApiKeys(keys); 
                setShowApiKeyModal(false); 
                isInitialLoadRef.current = true; 
                setCloudConfigVersion(v => v + 1); 
            }}
            onCancel={() => setShowApiKeyModal(false)}
        />
    );

    return (
        <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col font-sans">
            {cloudError && (
                <div className="bg-red-700 p-4 text-white text-center text-[11px] font-black flex flex-col items-center justify-center gap-4 sticky top-0 z-50 shadow-2xl border-b border-red-500/50">
                    <div className="flex items-center gap-3">
                        <ExclamationCircleIcon className="w-6 h-6 animate-pulse text-white" />
                        <span className="uppercase tracking-tighter leading-tight max-w-[250px] sm:max-w-none">
                            {isPermissionError ? 'TU BASE DE DATOS ESTÁ BLOQUEADA (REGLAS DE PRODUCCIÓN)' : cloudError}
                        </span>
                    </div>
                    <div className="flex flex-wrap items-center justify-center gap-3">
                        {isPermissionError && (
                            <>
                                <button 
                                    onClick={copyRulesDirectly} 
                                    className={`${rulesCopied ? 'bg-green-500' : 'bg-white text-red-700'} px-5 py-2 rounded-xl text-[10px] shadow-lg transition-all transform active:scale-95 font-black uppercase flex items-center gap-2`}
                                >
                                    {rulesCopied ? '✅ REGLAS COPIADAS' : '📋 COPIAR REGLAS SEGURAS'}
                                </button>
                                {firebaseConsoleUrl && (
                                    <a 
                                        href={firebaseConsoleUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="bg-blue-600 text-white px-5 py-2 rounded-xl text-[10px] shadow-lg transition-all transform active:scale-95 font-black uppercase border border-blue-400/50"
                                    >
                                        🌐 ABRIR FIREBASE RULES
                                    </a>
                                )}
                            </>
                        )}
                        <button 
                            onClick={() => setShowApiKeyModal(true)} 
                            className="bg-gray-800 text-gray-300 px-5 py-2 rounded-xl text-[10px] shadow-lg transition-all transform active:scale-95 font-black uppercase border border-gray-600"
                        >
                            ⚙️ RE-CONFIGURAR
                        </button>
                    </div>
                </div>
            )}
            <Header
                currentWeekTitle={getWeekTitle(currentDate)}
                onPrevWeek={() => setCurrentDate(d => { const n = new Date(d); n.setDate(n.getDate() - 7); return n; })}
                onNextWeek={() => setCurrentDate(d => { const n = new Date(d); n.setDate(n.getDate() + 7); return n; })}
                onCalendarClick={() => setIsCalendarOpen(true)}
                onLogout={() => setIsLogoutModalOpen(true)}
                isCloudConnected={isCloudConnected}
                syncStatus={syncStatus}
                cloudError={cloudError}
                onConfigureApi={() => setShowApiKeyModal(true)}
            />
            <main className="flex-grow py-4">
                <WeekView days={weekDays} onEditDay={setEditingDay} />
            </main>
            <Summary 
                totalHours={totalHours} 
                overtimeHours={overtimeHours}
                onDownload={async () => { setIsDownloading(true); await downloadScheduleAsPdf({ weekDays, currentDate, totalHours, overtimeHours }); setIsDownloading(false); }}
                isDownloading={isDownloading}
                onDownloadMonth={() => {}}
                isDownloadingMonth={false}
                onOpenCustomPeriodModal={() => setIsCustomPeriodModalOpen(true)}
                isDownloadingCustomPeriod={false}
            />
            {editingDay && <EditShiftModal day={editingDay} onClose={() => setEditingDay(null)} onSave={handleUpdateDay} templates={templates} onManageTemplates={() => setIsManagingTemplates(true)} />}
            {isManagingTemplates && <ManageTemplatesModal templates={templates} onAddTemplate={addTemplate} onDeleteTemplate={deleteTemplate} onClose={() => setIsManagingTemplates(false)} />}
            {isCalendarOpen && <CalendarPickerModal isOpen={isCalendarOpen} onClose={() => setIsCalendarOpen(false)} currentDate={currentDate} onDateSelect={(d) => { setCurrentDate(d); setIsCalendarOpen(false); }} />}
            {isLogoutModalOpen && <ConfirmModal isOpen={isLogoutModalOpen} title="Cerrar Sesión" message="¿Estás seguro de que quieres salir?" onConfirm={handleLogout} onCancel={() => setIsLogoutModalOpen(false)} />}
        </div>
    );
};

export default App;

import React, { useMemo, useState } from 'react';
import { LogoIcon, ChevronLeftIcon, ChevronRightIcon, CalendarIcon, LogoutIcon, CheckCircleIcon, ArrowPathIcon, ExclamationCircleIcon, Cog6ToothIcon } from './icons';
import { getApiKeys } from '../services/apiKeyService';

interface HeaderProps {
    currentWeekTitle: string;
    onPrevWeek: () => void;
    onNextWeek: () => void;
    onCalendarClick: () => void;
    onLogout: () => void;
    isCloudConnected: boolean;
    syncStatus: 'idle' | 'syncing' | 'success' | 'error';
    cloudError: string | null;
    onConfigureApi: () => void;
}

const Header: React.FC<HeaderProps> = ({ 
    currentWeekTitle, 
    onPrevWeek, 
    onNextWeek, 
    onCalendarClick, 
    onLogout,
    isCloudConnected,
    syncStatus,
    cloudError,
    onConfigureApi
}) => {
    const [showRules, setShowRules] = useState(false);
    const [copied, setCopied] = useState(false);

    const { consoleUrl, isDatabaseMissing, isPermissionDenied, hasKeys } = useMemo(() => {
        const keys = getApiKeys();
        if (keys && keys.apiKey) {
            try {
                const config = JSON.parse(keys.apiKey);
                const isMissing = cloudError?.includes('not-found') || cloudError?.includes('inexistente');
                const isDenied = cloudError?.toLowerCase().includes('bloqueo') || 
                                 cloudError?.toLowerCase().includes('permission') || 
                                 cloudError?.toLowerCase().includes('permisos') || 
                                 cloudError?.toLowerCase().includes('insufficient');

                let url = `https://console.firebase.google.com/project/${config.projectId}/firestore`;
                if (isDenied) {
                    url = `https://console.firebase.google.com/project/${config.projectId}/firestore/rules`;
                }

                return { 
                    consoleUrl: url,
                    isDatabaseMissing: isMissing,
                    isPermissionDenied: isDenied,
                    hasKeys: true
                };
            } catch (e) { return { consoleUrl: null, isDatabaseMissing: false, isPermissionDenied: false, hasKeys: false }; }
        }
        return { consoleUrl: null, isDatabaseMissing: false, isPermissionDenied: false, hasKeys: false };
    }, [cloudError]);

    const securityRules = `rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /schedules/{document} {
      allow read, write: if request.auth != null;
    }
  }
}`;

    const handleCopyRules = () => {
        navigator.clipboard.writeText(securityRules);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <header className="bg-gray-800 shadow-md p-3 sm:p-4 sticky top-0 z-20">
            <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">

                <div className="flex items-center justify-between w-full sm:w-auto">
                    <div className="flex items-center space-x-2">
                        <LogoIcon className="w-8 h-8 sm:w-10 sm:h-10" />
                        <h1 className="text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r from-red-500 to-red-700">Bienve App</h1>
                    </div>

                    <div className="flex items-center space-x-3 sm:ml-4">
                        {hasKeys ? (
                            <div className="flex items-center space-x-2">
                                {syncStatus === 'syncing' && <ArrowPathIcon className="w-5 h-5 text-blue-400 animate-spin" />}
                                {syncStatus === 'success' && <CheckCircleIcon className="w-5 h-5 text-green-500" />}
                                {(syncStatus === 'error' || cloudError) && (
                                    <div className="flex items-center group relative">
                                        <ExclamationCircleIcon className="w-6 h-6 text-red-500 cursor-pointer animate-pulse" />
                                        <div className="absolute left-0 sm:left-1/2 -translate-x-0 sm:-translate-x-1/2 top-full mt-2 w-72 bg-gray-900 text-white text-[11px] p-5 rounded-2xl shadow-2xl opacity-0 group-hover:opacity-100 transition-opacity z-50 border border-red-500/50 pointer-events-none group-hover:pointer-events-auto">
                                            <p className="font-bold text-red-400 mb-2 uppercase tracking-tighter text-xs text-center">
                                                {isDatabaseMissing ? '⚠️ Base de Datos Inexistente' : isPermissionDenied ? '🔒 Acceso Bloqueado (Producción)' : '⚠️ Error en Nube'}
                                            </p>
                                            <p className="mb-4 text-gray-300 leading-relaxed text-center">
                                                {isDatabaseMissing 
                                                    ? 'Entra en Firebase y dale al botón "Crear base de datos".' 
                                                    : isPermissionDenied 
                                                    ? 'Tu base de datos está en modo de Producción (if false). Debes permitir el acceso a usuarios autenticados.' 
                                                    : (cloudError || 'Error al conectar con la nube.')}
                                            </p>

                                            {isPermissionDenied && (
                                                <div className="mb-4">
                                                    <button 
                                                        onClick={() => setShowRules(!showRules)}
                                                        className="w-full mb-2 bg-blue-600/20 text-blue-400 py-2 rounded-lg text-[10px] font-bold border border-blue-500/30"
                                                    >
                                                        {showRules ? 'OCULTAR REGLAS' : 'VER REGLAS PARA COPIAR'}
                                                    </button>
                                                    {showRules && (
                                                        <div className="relative">
                                                            <div className="bg-black p-3 rounded-xl border border-gray-800 mb-2">
                                                                <pre className="text-[9px] text-green-400 overflow-x-auto whitespace-pre">
                                                                    {securityRules}
                                                                </pre>
                                                            </div>
                                                            <button 
                                                                onClick={handleCopyRules}
                                                                className={`w-full py-2 rounded-lg text-[9px] font-black uppercase transition-all ${copied ? 'bg-green-600 text-white' : 'bg-gray-700 text-gray-300 hover:bg-gray-600'}`}
                                                            >
                                                                {copied ? '✅ ¡COPIADO!' : '📋 COPIAR REGLAS'}
                                                            </button>
                                                        </div>
                                                    )}
                                                </div>
                                            )}

                                            {consoleUrl && (
                                                <a 
                                                    href={consoleUrl} 
                                                    target="_blank" 
                                                    rel="noopener noreferrer"
                                                    className="block w-full bg-red-600 hover:bg-red-500 text-center py-2.5 rounded-xl font-black text-white transition-colors uppercase text-[10px]"
                                                >
                                                    {isDatabaseMissing ? 'IR A CREAR BASE DE DATOS' : isPermissionDenied ? 'ABRIR PESTAÑA REGLAS' : 'REVISAR CONSOLA'}
                                                </a>
                                            )}
                                            <button onClick={onConfigureApi} className="mt-4 w-full text-gray-500 hover:text-white text-[9px] uppercase font-bold tracking-widest border-t border-gray-800 pt-2">Cambiar Configuración Cloud</button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <button onClick={onConfigureApi} className="text-xs text-yellow-500 flex items-center space-x-1 bg-yellow-500/10 px-3 py-1.5 rounded-full border border-yellow-500/20 hover:bg-yellow-500/20 transition-colors">
                                <Cog6ToothIcon className="w-3 h-3" />
                                <span>Configurar Nube</span>
                            </button>
                        )}
                    </div>
                </div>

                <div className="flex items-center justify-center bg-gray-900/50 p-1 rounded-full border border-gray-700">
                    <button onClick={onPrevWeek} className="p-2 text-gray-400 hover:text-white rounded-full"><ChevronLeftIcon className="w-5 h-5" /></button>
                    <button onClick={onCalendarClick} className="flex items-center space-x-2 px-4 py-1 text-sm font-medium text-red-400">
                        <CalendarIcon className="w-4 h-4" />
                        <span className="truncate max-w-[150px]">{currentWeekTitle}</span>
                    </button>
                    <button onClick={onNextWeek} className="p-2 text-gray-400 hover:text-white rounded-full"><ChevronRightIcon className="w-5 h-5" /></button>
                </div>

                <button onClick={onLogout} className="hidden sm:block p-2 text-gray-400 hover:text-red-500"><LogoutIcon className="w-6 h-6" /></button>
            </div>
        </header>
    );
};

export default Header;

