export const API_KEYS_STORAGE_KEY = 'bienve_cloud_config_v3';

export interface ApiKeys {
    clientId: string;
    apiKey: string;
}

/**
 * Intenta obtener la configuración de la nube.
 * Prioridad: LocalStorage > Backup LocalStorage > Variable de Entorno.
 */
export const getApiKeys = (): ApiKeys | null => {
    try {
        // 1. Intentar desde LocalStorage principal
        let storedData = localStorage.getItem(API_KEYS_STORAGE_KEY);

        // 2. Intentar desde Backup si la principal falló
        if (!storedData) {
            storedData = localStorage.getItem(API_KEYS_STORAGE_KEY + '_backup');
        }

        if (storedData) {
            const parsed = JSON.parse(storedData);
            if (parsed && parsed.apiKey && (parsed.apiKey.includes('projectId') || parsed.apiKey.includes('apiKey'))) {
                return parsed;
            }
        }

        // 3. FALLBACK INTELIGENTE: Si estamos en producción y existe la variable de entorno, usarla.
        // Esto evita que la app pida configuración si ya se definió en Vercel.
        const envConfig = (process.env as any).FIREBASE_CONFIG;
        if (envConfig) {
            console.log("Cargando configuración predeterminada desde entorno.");
            return {
                clientId: 'firebase_env',
                apiKey: typeof envConfig === 'string' ? envConfig : JSON.stringify(envConfig)
            };
        }
    } catch (error) {
        console.error("Error al recuperar configuración del dispositivo:", error);
    }
    return null;
};

export const saveApiKeys = (keys: ApiKeys): void => {
    try {
        if (!keys.apiKey || keys.apiKey.trim() === '') return;
        const data = JSON.stringify(keys);
        localStorage.setItem(API_KEYS_STORAGE_KEY, data);
        localStorage.setItem(API_KEYS_STORAGE_KEY + '_backup', data);
    } catch (error) {
        console.error("Error al guardar configuración:", error);
    }
};

export const areKeysSet = (): boolean => {
    return getApiKeys() !== null;
};

export const clearApiKeys = (): void => {
    try {
        localStorage.removeItem(API_KEYS_STORAGE_KEY);
        localStorage.removeItem(API_KEYS_STORAGE_KEY + '_backup');
    } catch (error) {
        console.error("Error al borrar configuración:", error);
    }
};

