import React from 'react';
import { Day, DayStatus } from '../types';
import { calculateHoursFromShift } from '../services/scheduleService';
import { formatDayDate, formatDayName } from '../utils/dateUtils';
import { StarIcon, SunIcon } from './icons';

interface DayCardProps {
    day: Day;
    onEdit: (day: Day) => void;
    isToday: boolean;
}

const DayCard: React.FC<DayCardProps> = ({ day, onEdit, isToday }) => {
    const hours = calculateHoursFromShift(day.shift);
    const shiftLower = day.shift.toLowerCase();

    const getShiftGradient = () => {
        if (day.status === DayStatus.Vacation) return 'from-emerald-600 to-teal-900 border-emerald-500/50';
        if (day.status === DayStatus.Holiday) return 'from-indigo-600 to-purple-900 border-indigo-500/50';

        if (!day.shift) return 'from-gray-800 to-gray-900 border-gray-700';

        // Colores lógicos por tipo de turno
        if (shiftLower.includes('partido') || (shiftLower.includes('12') && shiftLower.includes('20'))) 
            return 'from-orange-600 to-red-900 border-orange-500/50'; // Partido = Calor/Energía
        if (shiftLower.includes('22') || shiftLower.includes('noche')) 
            return 'from-slate-700 to-slate-950 border-slate-500/50'; // Noche = Oscuro
        if (parseInt(day.shift) < 12) 
            return 'from-sky-500 to-blue-800 border-sky-400/50'; // Mañana = Cielo despejado

        return 'from-blue-600 to-indigo-900 border-blue-500/50'; // Tarde = Atardecer
    };

    const baseClasses = "relative rounded-3xl shadow-2xl w-full h-44 flex flex-col justify-between border-2 transition-all duration-500 ease-out transform hover:scale-[1.02] active:scale-95 focus:outline-none overflow-hidden group";
    const todayClasses = isToday ? 'ring-4 ring-white/30 scale-[1.02] z-10 shadow-red-500/20' : '';

    return (
        <button
            type="button"
            className={`${baseClasses} ${todayClasses} bg-gradient-to-br ${getShiftGradient()}`}
            onClick={() => onEdit(day)}
        >
            {/* Efecto de brillo al pasar el dedo/mouse */}
            <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

            <div className="relative z-10 p-4 w-full h-full flex flex-col justify-between">
                <div className="flex justify-between items-start">
                    <div>
                        <p className="font-black text-xs uppercase tracking-widest text-white/60">{formatDayName(day.date).substring(0, 3)}</p>
                        <p className="font-bold text-2xl text-white">{formatDayDate(day.date)}</p>
                    </div>
                    {isToday && (
                        <span className="bg-white text-black text-[10px] font-black px-2 py-1 rounded-full uppercase tracking-tighter shadow-lg">Hoy</span>
                    )}
                </div>

                <div className="text-center">
                    {day.status === DayStatus.Vacation ? (
                        <SunIcon className="w-10 h-10 mx-auto text-white/80 animate-pulse" />
                    ) : day.status === DayStatus.Holiday ? (
                        <StarIcon className="w-10 h-10 mx-auto text-white/80" />
                    ) : (
                        <p className="text-3xl font-black text-white drop-shadow-md truncate">
                            {day.shift || '—'}
                        </p>
                    )}
                </div>

                <div className="flex justify-between items-end">
                    <p className="text-[10px] font-bold text-white/50 uppercase tracking-widest">
                        {day.status === DayStatus.Work ? 'Turno' : day.status === DayStatus.Vacation ? 'Relax' : 'Festivo'}
                    </p>
                    {hours > 0 && (
                        <p className="text-sm font-black text-black bg-white/90 px-3 py-1 rounded-2xl shadow-sm">
                            {hours.toFixed(1)}h
                        </p>
                    )}
                </div>
            </div>
        </button>
    );
};

